#define main archived_cli_main
#include "../ssm-cuda/main.cu"
#undef main
#include <vector>
#include <fstream>
#include <string>
#include <iostream>
#include <iomanip>
using VF=std::vector<float>;
template<class T>std::vector<T> readbin(const std::string&p){std::ifstream f(p,std::ios::binary|std::ios::ate);auto n=f.tellg();f.seekg(0);std::vector<T>x(size_t(n)/sizeof(T));f.read((char*)x.data(),n);return x;}
struct F{int batch,dim,L,chain;VF h[9];float*a[9],*st;std::vector<float*>ys;};
void reset(F&f){VF h(f.h[8].size()+17,-12345);std::copy(f.h[8].begin(),f.h[8].end(),h.begin());GPU_CHECK(cudaMemcpy(f.st,h.data(),h.size()*4,cudaMemcpyHostToDevice));VF y(f.h[0].size()+17,-12345);for(auto p:f.ys)GPU_CHECK(cudaMemcpy(p,y.data(),y.size()*4,cudaMemcpyHostToDevice));GPU_CHECK(cudaDeviceSynchronize());}
void launch(F&f,float*y){int tx=std::min(f.dim,1024);selective_scan_base<<<dim3(f.batch,(f.dim+tx-1)/tx),tx>>>(f.a[0],f.a[1],f.a[2],f.a[3],f.a[4],f.a[5],f.a[6],f.a[7],true,f.batch,f.dim,8,f.L,f.st,y);GPU_CHECK(cudaGetLastError());}
int main(){std::string root=std::string(__FILE__).substr(0,std::string(__FILE__).find_last_of('/'));auto input=readbin<float>(root+"/fixture.bin");auto gold=readbin<double>(root+"/expected_outputs.bin");size_t pos=1;std::vector<F>fs;
for(int ci=0;ci<int(input[0]);ci++){F base;base.batch=int(input[pos++]);base.dim=int(input[pos++]);base.L=int(input[pos++]);for(int j=0;j<9;j++){size_t n=size_t(input[pos++]);base.h[j]=VF(input.begin()+pos,input.begin()+pos+n);pos+=n;GPU_CHECK(cudaMalloc(&base.a[j],n*4));GPU_CHECK(cudaMemcpy(base.a[j],base.h[j].data(),n*4,cudaMemcpyHostToDevice));}for(int chain:{1,3}){F f=base;f.chain=chain;GPU_CHECK(cudaMalloc(&f.st,(f.h[8].size()+17)*4));for(int k=0;k<chain;k++){float*y;GPU_CHECK(cudaMalloc(&y,(f.h[0].size()+17)*4));f.ys.push_back(y);}fs.push_back(f);}}
for(auto&f:fs){reset(f);for(auto y:f.ys)launch(f,y);GPU_CHECK(cudaDeviceSynchronize());}
for(int trial=1;trial<=5;trial++){VF got;std::vector<double>times;double cpuerr=0;for(auto&f:fs){reset(f);auto st=std::chrono::steady_clock::now();for(auto y:f.ys)launch(f,y);GPU_CHECK(cudaDeviceSynchronize());times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count());VF cpuS=f.h[8],cpuY(f.h[0].size());for(auto y:f.ys){VF h(f.h[0].size()+17);GPU_CHECK(cudaMemcpy(h.data(),y,h.size()*4,cudaMemcpyDeviceToHost));selective_scan_ref(f.h[0].data(),f.h[1].data(),f.h[2].data(),f.h[3].data(),f.h[4].data(),f.h[5].data(),f.h[6].data(),f.h[7].data(),true,f.batch,f.dim,8,f.L,cpuS.data(),cpuY.data());for(size_t i=0;i<cpuY.size();i++)cpuerr=std::max(cpuerr,std::abs(double(h[i])-cpuY[i]));got.insert(got.end(),h.begin(),h.end());}VF h(f.h[8].size()+17);GPU_CHECK(cudaMemcpy(h.data(),f.st,h.size()*4,cudaMemcpyDeviceToHost));for(size_t i=0;i<cpuS.size();i++)cpuerr=std::max(cpuerr,std::abs(double(h[i])-cpuS[i]));got.insert(got.end(),h.begin(),h.end());}
bool ok=got.size()==gold.size();double ma=0,mr=0,sum=0;for(size_t i=0;i<got.size();i++){double e=std::abs(double(got[i])-gold[i]);ma=std::max(ma,e);mr=std::max(mr,e/std::max(std::abs(gold[i]),1e-12));ok &=std::isfinite(got[i])&&(gold[i]==-12345 ? got[i]==-12345 : e<=1e-3);}ok &=cpuerr<=1e-3;for(auto t:times)sum+=t;std::string file="output_trial"+std::to_string(trial)+".bin";std::ofstream out(file,std::ios::binary);out.write((char*)input.data(),input.size()*4);out.write((char*)got.data(),got.size()*4);out.close();std::cout<<std::setprecision(17)<<"STUDY_TRIAL {\"trial\":"<<trial<<",\"time_seconds\":"<<sum<<",\"correct\":"<<(ok?"true":"false")<<",\"checked_values\":"<<got.size()<<",\"max_abs_error\":"<<ma<<",\"max_rel_error\":"<<mr<<",\"source_CPU_max_abs_error\":"<<cpuerr<<",\"timing_region\":\"sum6_serialbase_recurrence_chain_paths\",\"jit_excluded\":true,\"internal_repeats\":1,\"per_path_times_seconds\":[";for(size_t i=0;i<times.size();i++){if(i)std::cout<<",";std::cout<<times[i];}std::cout<<"],\"output_artifact\":{\"path\":\""<<file<<"\",\"dtype\":\"float32\",\"count\":"<<input.size()+got.size()<<",\"byte_order\":\"little\"}}\n";}}
